-- Development 27: authoritative 430-question bank and stamp rewards.
begin;

alter table public.point_transactions drop constraint if exists point_transactions_reason_check;
alter table public.point_transactions add constraint point_transactions_reason_check check(reason in (
 'spot_post','spot_like','quiz','gacha_cost','gacha_prize','admin','aed_new_approval',
 'weekly_quiz_stamp_reward','aed_stamp_reward'
));

-- New point rules apply only to future activity. Existing ledger entries are preserved.
create or replace function public.award_spot_post_points() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare n integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(new.created_by::text,2202));
 select count(*) into n from public.point_transactions where user_id=new.created_by and reason='spot_post'
 and created_at >= date_trunc('day',now() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo';
 if n<5 then perform public.apply_point_transaction(new.created_by,1,'spot_post',new.id::text); end if;
 return new;
end$$;

create or replace function public.vote_spot(p_spot_id bigint,p_kind text) returns bigint
language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); n bigint; owner_id uuid; earned integer;
begin
 if u is null then raise exception 'authentication_required' using errcode='28000'; end if;
 if not public.is_user_active(u) then raise exception 'account_suspended' using errcode='42501'; end if;
 if p_kind not in ('like','report','confirm') then raise exception 'invalid_vote_kind'; end if;
 select created_by into owner_id from public.spots where id=p_spot_id;
 if not found then raise exception 'spot_not_found'; end if;
 if p_kind='like' and owner_id=u then raise exception 'cannot_like_own_spot'; end if;
 perform pg_advisory_xact_lock(hashtextextended('spot-like:'||u::text,0));
 insert into public.spot_votes(spot_id,user_id,kind) values(p_spot_id,u,p_kind) on conflict do nothing;
 if not found then raise exception 'already_voted' using errcode='23505'; end if;
 if p_kind='like' then
  update public.spots set like_count=coalesce(like_count,0)+1 where id=p_spot_id returning like_count into n;
  select count(*) into earned from public.point_transactions where user_id=u and reason='spot_like'
   and created_at>=date_trunc('day',now() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo';
  if earned<5 then perform public.apply_point_transaction(u,1,'spot_like',p_spot_id::text); end if;
 elsif p_kind='report' then update public.spots set report_count=coalesce(report_count,0)+1 where id=p_spot_id returning report_count into n;
 else update public.spots set confirm_count=coalesce(confirm_count,0)+1 where id=p_spot_id returning confirm_count into n; end if;
 return n;
end$$;

truncate app_private.quiz_questions;
insert into app_private.quiz_questions(id,mode,body)
select x->>'id',x->>'mode',jsonb_build_object('q',x->>'q','o',x->'o','a',(x->>'a')::int,'e',x->>'e','sign',x->'sign')
from jsonb_array_elements('[{"id":"CAR-001","mode":"car","q":"黄色信号に変わったときの対応として正しいものは？","o":["安全に停止できるなら停止する","黄色なら必ず加速して通過する","どんな状況でも急ブレーキで停止する"],"a":0,"e":"黄色信号では原則として停止位置から先へ進めません。黄色に変わった時点ですでに停止位置に近く、安全に停止できない場合に限り、そのまま進むことができます。","sign":null},{"id":"CAR-002","mode":"car","q":"赤色の点滅信号で普通自動車が取るべき行動は？","o":["徐行してそのまま通過する","一時停止して安全を確認する","青信号と同じように進む"],"a":1,"e":"赤色点滅では、車は停止位置で一時停止しなければなりません。徐行だけでは足りません。","sign":null},{"id":"CAR-003","mode":"car","q":"黄色の点滅信号の意味として正しいものは？","o":["必ず一時停止する","他の交通に注意して進む","進行してはいけない"],"a":1,"e":"黄色点滅は、他の交通に注意して進行できます。赤色点滅の『一時停止』と混同しやすいポイントです。","sign":null},{"id":"CAR-004","mode":"car","q":"対面信号が赤で、青色の右向き矢印が出ている。普通自動車はどうする？","o":["右折できる","直進だけできる","全方向へ進めない"],"a":0,"e":"青色の矢印信号が出ている場合、車は赤・黄信号でも矢印の方向に進めます。右向き矢印では、別の禁止規制がなければ転回も可能です。","sign":null},{"id":"CAR-005","mode":"car","q":"「車両進入禁止」の標識がある方向からの進入について正しいものは？","o":["対向車がいなければ進入できる","夜間だけ進入できる","原則として進入できない"],"a":2,"e":"車両進入禁止は、その方向から車両が進入することを禁止する規制標識です。交通量の有無で解除されません。","sign":null},{"id":"CAR-006","mode":"car","q":"「車両通行止め」と「車両進入禁止」の関係として正しいものは？","o":["同じ意味の標識である","別の意味を持つ標識である","どちらも歩行者だけを対象とする"],"a":1,"e":"別の標識です。車両通行止めは対象道路での車両通行を禁止し、車両進入禁止は表示された側からの進入を禁止します。一方通行の出口側などで進入禁止が使われます。","sign":null},{"id":"CAR-007","mode":"car","q":"一方通行道路を逆方向へ走ることについて正しいものは？","o":["短距離ならよい","対向車がいなくても原則できない","ハザードを出せばよい"],"a":1,"e":"一方通行規制は交通状況にかかわらず守る必要があります。補助標識等で除外されている車両を除き、逆方向には進めません。","sign":null},{"id":"CAR-008","mode":"car","q":"指定方向外進行禁止で「直進・左折」のみ示されている交差点。できる進行は？","o":["直進と左折","直進・左折・右折","右折だけ"],"a":0,"e":"指定方向外進行禁止では、標識で示された方向以外へ進行できません。安全かどうかとは別の規制です。","sign":null},{"id":"CAR-009","mode":"car","q":"転回禁止の場所でUターンしてよい条件は？","o":["周囲に車がいないとき","夜間だけ","標識の規制中は原則できない"],"a":2,"e":"転回禁止は、周囲に車がいるかどうかにかかわらず適用されます。","sign":null},{"id":"CAR-010","mode":"car","q":"「駐車禁止」の標識だけがある場所での短時間の乗降について正しいものは？","o":["短時間の停車まで標識だけで一律禁止とは限らない","1秒でも必ず違反になる","5分以内なら必ず駐車扱いにならない"],"a":0,"e":"駐車禁止と駐停車禁止は別です。駐車禁止標識だけなら『停車』まで一律に禁止する標識ではありません。ただし、交差点付近など法律上の駐停車禁止場所では短時間でも原則停車できません。","sign":null},{"id":"CAR-011","mode":"car","q":"「駐停車禁止」の標識がある場所で、客を数秒で降ろす場合は？","o":["原則として停車できない","1分以内なら停車できる","ハザードを点ければ停車できる"],"a":0,"e":"駐停車禁止は『駐車』だけでなく『停車』も禁止します。信号や危険防止など法令上必要な停止は別です。","sign":null},{"id":"CAR-012","mode":"car","q":"最高速度40km/hの標識がある道路で正しい運転は？","o":["必ず40km/hで走る","40km/h以下で道路状況に応じた安全な速度で走る","空いていれば50km/hまでよい"],"a":1,"e":"40km/hは『出さなければならない速度』ではなく上限です。上限内でも道路・交通・天候・視界に応じた安全な速度で走る必要があります。","sign":null},{"id":"CAR-013","mode":"car","q":"規制標識の下に補助標識「8-20」がある。意味は？","o":["原則8時から20時まで規制が適用される","20時から翌8時まで規制される","8月20日だけ規制される"],"a":0,"e":"補助標識の『日・時間』は、本標識の規制が適用される日や時間を限定します。","sign":null},{"id":"CAR-014","mode":"car","q":"進入禁止標識の下に「日曜・休日を除く」とある。日曜・休日は？","o":["その標識による進入禁止の対象外","平日より厳しく規制される","補助標識は無効なので常に進入禁止"],"a":0,"e":"補助標識は本標識の規制対象を限定します。この場合、日曜・休日はその進入禁止規制から除外されます。","sign":null},{"id":"CAR-015","mode":"car","q":"車両通行帯の境界が黄色線の場合、進路変更は？","o":["前車が遅ければ越えてよい","原則その黄色線を越えて進路変更できない","ウインカーを出せば越えられる"],"a":1,"e":"黄色線で区画された車両通行帯では、その黄色線を越える進路変更は禁止です。","sign":null},{"id":"CAR-016","mode":"car","q":"黄色の中央線で、自転車を追い越すため右側部分へはみ出すことは？","o":["自転車相手なら常にできる","クラクションを鳴らせばできる","追越しのためのはみ出し禁止規制があるならできない"],"a":2,"e":"黄色の中央線等で『追越しのための右側部分はみ出し通行禁止』が示されている場合、相手が自転車だから自由にはみ出せるわけではありません。","sign":null},{"id":"CAR-017","mode":"car","q":"交差点で右左折するとき、方向指示器を出し始める時期は？","o":["交差点の約30m手前","交差点の約3m手前","ハンドルを切った後"],"a":0,"e":"交差点での右左折は、その地点の30m手前に達したときから合図します。","sign":null},{"id":"CAR-018","mode":"car","q":"車線変更の合図を出し始める時期は？","o":["進路変更の約3秒前","進路変更の約30秒前","車線変更が終わった後"],"a":0,"e":"車線変更などの進路変更では、進路を変えようとする約3秒前から合図します。右左折の『30m手前』とは別です。","sign":null},{"id":"CAR-019","mode":"car","q":"必要がないのに方向指示器を長時間出し続ける行為は？","o":["安全のため推奨される","必要のない合図はしてはいけない","速度30km/h以下ならよい"],"a":1,"e":"必要がないのに合図をしてはいけません。行為を終えたら速やかに合図をやめる必要があります。","sign":null},{"id":"CAR-020","mode":"car","q":"知人へのあいさつ目的でクラクションを鳴らすことは？","o":["短く1回ならよい","原則として目的外使用になる","昼間ならよい"],"a":1,"e":"警音器は『警笛鳴らせ』等の指定場所や危険回避のためやむを得ない場合などに使用します。挨拶目的では使用できません。","sign":null},{"id":"BIKE-001","mode":"bike","q":"道路交通法上の自転車の位置付けとして正しいものは？","o":["歩行者","軽車両","原動機付自転車"],"a":1,"e":"自転車は軽車両であり、車両の一種です。押して歩く場合などは歩行者として扱われます。","sign":null},{"id":"BIKE-002","mode":"bike","q":"2026年4月からの自転車の青切符制度の対象年齢は？","o":["原則16歳以上","原則13歳以上","年齢制限なし"],"a":0,"e":"自転車の交通反則通告制度（青切符）の対象は16歳以上です。16歳未満は青切符の対象ではなく、個別の事案に応じた違反処理となります。","sign":null},{"id":"BIKE-003","mode":"bike","q":"2026年4月以降の自転車取締りについて正しいものは？","o":["軽微な違反でも原則すべて即青切符","基本は指導警告で、悪質・危険な違反などが検挙対象","自転車違反は一切取り締まられない"],"a":1,"e":"青切符導入後も基本的には指導警告が行われます。事故原因となるような悪質・危険な違反などが検挙対象です。","sign":null},{"id":"BIKE-004","mode":"bike","q":"目的地が道路の右側にある場合、自転車の通行方法として正しいものは？","o":["短距離なら右側を逆走できる","原則として車道の左側を通行する","歩道があれば必ず歩道を走る"],"a":1,"e":"自転車は原則として車道の左側を通行します。目的地が右側にあることは右側通行の理由にはなりません。","sign":null},{"id":"BIKE-005","mode":"bike","q":"普通自転車が歩道を通行できる条件について正しいものは？","o":["運転者が危険だと感じればいつでも自由","法律上の一定の例外に該当する場合","車道が混んでいれば必ず歩道"],"a":1,"e":"自転車は車道通行が原則で、歩道は例外です。標識・年齢・身体状況や、車道・交通状況から安全確保のためやむを得ない場合など、一定の条件があります。","sign":null},{"id":"BIKE-006","mode":"bike","q":"13歳未満の人が普通自転車を運転する場合、歩道通行は？","o":["一定の例外として認められる","絶対に認められない","夜間だけ認められる"],"a":0,"e":"13歳未満の人が普通自転車を運転する場合は、歩道を通行できる例外に該当します。ただし歩行者優先など歩道上のルールは守る必要があります。","sign":null},{"id":"BIKE-007","mode":"bike","q":"70歳以上の人の普通自転車の歩道通行について正しいものは？","o":["年齢による例外はない","一定の例外として認められる","80歳以上だけ認められる"],"a":1,"e":"70歳以上の人が普通自転車を運転する場合は、歩道通行が認められる例外の一つです。","sign":null},{"id":"BIKE-008","mode":"bike","q":"車道通行に支障がある身体の不自由な人が普通自転車を運転する場合は？","o":["一定の歩道通行例外がある","歩道通行は一切できない","警察官が同行する場合だけ歩道可"],"a":0,"e":"一定の身体の不自由な人が普通自転車を運転する場合も歩道通行例外に含まれます。","sign":null},{"id":"BIKE-009","mode":"bike","q":"成人でも車道・交通状況から安全確保のためやむを得ないと認められる場合、普通自転車は？","o":["歩道通行できる場合がある","必ず車道を走る","自転車から降りても歩道を通れない"],"a":0,"e":"年齢等だけでなく、車道・交通状況から通行の安全を確保するためやむを得ない場合も歩道通行の例外です。","sign":null},{"id":"BIKE-010","mode":"bike","q":"普通自転車が例外的に歩道を通行するときの基本は？","o":["歩道中央を高速走行","車道寄りを徐行","歩行者が避けるので速度自由"],"a":1,"e":"歩道通行が認められる場合でも、車道寄りの部分を徐行するのが原則です。普通自転車通行指定部分がある場合はその指定部分を通行します。","sign":null},{"id":"BIKE-011","mode":"bike","q":"自転車通行可の歩道で歩行者の通行を妨げる場合は？","o":["ベルを鳴らして進む","自転車が一時停止する","歩行者に避けてもらう"],"a":1,"e":"歩道は歩行者優先です。歩行者の通行を妨げる場合、自転車は一時停止しなければなりません。","sign":null},{"id":"BIKE-012","mode":"bike","q":"歩行者用信号に「歩行者・自転車専用」と表示されている場合、自転車は？","o":["その歩行者用信号に従う","車両用信号だけに従う","どちらの信号も無視できる"],"a":0,"e":"『歩行者・自転車専用』表示がある歩行者用信号では、自転車もその信号に従います。","sign":null},{"id":"BIKE-013","mode":"bike","q":"自転車で赤信号に直面した場合は？","o":["車が来ていなければ進める","信号に従って停止する","免許不要なので信号は任意"],"a":1,"e":"自転車も車両であり、信号に従う義務があります。16歳以上で悪質・危険な違反として青切符の対象となった場合、信号無視の反則金は6,000円です。","sign":null},{"id":"BIKE-014","mode":"bike","q":"自転車が赤色点滅信号に直面した場合は？","o":["徐行だけで通過する","一時停止して安全確認する","自転車だけは青信号扱い"],"a":1,"e":"赤色点滅では自転車を含む車両は停止位置で一時停止が必要です。青切符対象となった場合、点滅信号無視の反則金は5,000円です。","sign":null},{"id":"BIKE-015","mode":"bike","q":"自転車の「止まれ」標識への対応は？","o":["十分減速だけでよい","完全に一時停止する","ベルを鳴らせば停止不要"],"a":1,"e":"一時停止は徐行ではありません。停止線の直前などで完全に停止し、安全確認する必要があります。","sign":null},{"id":"BIKE-016","mode":"bike","q":"夜間、街灯が明るい道路を自転車で走る場合の前照灯は？","o":["街灯があれば不要","点灯する必要がある","歩道走行時だけ不要"],"a":1,"e":"夜間は前照灯を点灯する必要があります。街灯の明るさを理由に無灯火にできません。","sign":null},{"id":"BIKE-017","mode":"bike","q":"自転車ヘルメット未着用について正しいものは？","o":["未着用自体に青切符の反則金がある","着用は努力義務で、未着用自体の青切符反則金はない","16歳以上だけ着用義務がない"],"a":1,"e":"自転車の乗車用ヘルメット着用は努力義務です。未着用そのものに青切符の反則金は設定されていません。","sign":null},{"id":"BIKE-018","mode":"bike","q":"自転車でスマホを手に持って通話する行為は？","o":["画面を見なければ問題ない","携帯電話使用等（保持）の対象になり得る","停止中も必ず違反になる"],"a":1,"e":"手に持って通話する行為も携帯電話使用等（保持）に含まれます。16歳以上で青切符となった場合の反則金は12,000円です。","sign":null},{"id":"BIKE-019","mode":"bike","q":"ながらスマホで実際に交通の危険を生じさせた場合は？","o":["必ず12,000円の青切符だけで終わる","刑事手続の対象となる場合がある","自転車なので処罰されない"],"a":1,"e":"実際に交通の危険を生じさせた場合などは、青切符ではなく刑事手続の対象となることがあります。","sign":null},{"id":"BIKE-020","mode":"bike","q":"自転車の飲酒運転について正しいものは？","o":["すべて青切符だけで処理される","重大な違反は刑事手続の対象になる","自動車免許がなければ違反にならない"],"a":1,"e":"飲酒運転は重大な違反で、酒酔い運転などは赤切符（刑事手続）の対象です。『自転車＝青切符で全部終わる』ではありません。","sign":null},{"id":"CAR-021","mode":"car","q":"「警笛区間」の標識がある区間で正しい警音器の使い方は？","o":["区間中ずっと鳴らし続ける","必要な見通しの悪い場所などで鳴らす","一切鳴らしてはいけない"],"a":1,"e":"警笛区間では、見通しのきかない交差点・曲がり角・上り坂の頂上などを通るときに鳴らします。区間中ずっと鳴らす意味ではありません。","sign":null},{"id":"CAR-022","mode":"car","q":"信号機で交通整理されている、左右の見通しが悪い交差点。『見通しが悪い』ことだけを理由とする徐行義務は？","o":["交通整理されていても必ず同じ徐行義務がある","この徐行規定の例外となる","夜間だけ例外となる"],"a":1,"e":"見通しのきかない交差点は原則徐行ですが、信号機等による交通整理が行われている場合や優先道路を通行している場合は、この徐行規定の例外です。","sign":null},{"id":"CAR-023","mode":"car","q":"道路の曲がり角付近での運転は？","o":["徐行標識がなくても徐行する","標識がなければ通常速度でよい","対向車がいる時だけ徐行する"],"a":0,"e":"道路の曲がり角付近は法令上の徐行場所です。徐行は『すぐ停止できるような速度』をいいます。","sign":null},{"id":"CAR-024","mode":"car","q":"上り坂の頂上付近と、こう配の急な下り坂について正しいものは？","o":["上り坂だけ徐行場所","下り坂だけ徐行場所","どちらも徐行場所"],"a":2,"e":"上り坂の頂上付近も、こう配の急な下り坂も徐行場所です。","sign":null},{"id":"CAR-025","mode":"car","q":"転回禁止標識がない場所でも、他車や歩行者の正常な通行を妨げるおそれがある場合は？","o":["転回してよい","転回してはいけない","クラクションを鳴らせば転回できる"],"a":1,"e":"横断・転回・後退などは、歩行者や他車の正常な通行を妨げるおそれがある場合は禁止されます。","sign":null},{"id":"CAR-026","mode":"car","q":"他の車を追い越すときの基本は？","o":["原則として右側を通る","原則として左側を通る","どちら側でも自由"],"a":0,"e":"追越しは原則として前車の右側を通ります。ただし、前車が右折のため中央等へ寄っている場合や路面電車を追い越す場合などは例外があります。","sign":null},{"id":"CAR-027","mode":"car","q":"前車が右折のため道路中央へ寄っている。追い越す場合の基本は？","o":["右側から追い越す","左側から追い越す","中央線上を走る"],"a":1,"e":"前車が右折のため道路中央（一方通行では右端）に寄っている場合、追越しはその左側を通ります。","sign":null},{"id":"CAR-028","mode":"car","q":"横断歩道の手前30m以内で、歩行者が見当たらない場合の追越し・追抜きは？","o":["歩行者がいなければよい","原則禁止される","夜間だけできる"],"a":1,"e":"横断歩道・自転車横断帯とその手前30m以内では、他車の追越し・追抜きは禁止されています。","sign":null},{"id":"CAR-029","mode":"car","q":"交差点の手前30m以内の追越し規制について正しいものは？","o":["どんな道路でも例外なく禁止","優先道路を通行中など例外がある","信号が青なら常に追越しできる"],"a":1,"e":"交差点とその手前30m以内は原則追越し禁止ですが、優先道路を通行している場合はこの規定の例外です。","sign":null},{"id":"CAR-030","mode":"car","q":"トンネル内の追越しについて正しいものは？","o":["車両通行帯がある場合は場所規制の例外がある","車両通行帯があっても常に一切禁止","照明が明るければ自由"],"a":0,"e":"トンネルは追越し禁止場所の一つですが、車両通行帯がある場合はこの場所規制の例外です。もちろん他の禁止条件があれば従う必要があります。","sign":null},{"id":"CAR-031","mode":"car","q":"後続車に追い越されている最中の対応は？","o":["制限速度内なら加速してよい","追越しが終わるまで速度を上げない","必ず路肩に停止する"],"a":1,"e":"追い越されるときは、追越しが終わるまで速度を上げてはいけません。","sign":null},{"id":"CAR-032","mode":"car","q":"横断歩道で歩行者が渡ろうとしているが、まだ歩道上にいる。車は？","o":["歩行者が車道に出る前なら先に通れる","一時停止して歩行者を優先する","クラクションで注意して通過する"],"a":1,"e":"横断中だけでなく『横断しようとしている』歩行者がいる場合も、横断歩道等の手前で一時停止して道を譲る必要があります。","sign":null},{"id":"CAR-033","mode":"car","q":"横断歩道に歩行者や自転車がいないことが明らかな場合、接近時の速度は？","o":["必ず停止する","必ず停止できる速度まで落とす","『いないことが明らか』ならその減速義務の例外"],"a":2,"e":"横断する歩行者や自転車がいないことが明らかな場合は、横断歩道接近時の『停止できる速度まで落とす』義務の例外です。","sign":null},{"id":"CAR-034","mode":"car","q":"横断歩道直前で車が停止している。歩行者が見えない場合、側方を通って前へ出る前に？","o":["一時停止が必要","そのまま徐行で通過できる","クラクションを鳴らせばよい"],"a":0,"e":"停止車両の陰から横断者が出る可能性があるため、横断歩道等の手前で止まっている車の側方を通って前方へ出る前には一時停止が必要です。","sign":null},{"id":"CAR-035","mode":"car","q":"横断歩道のない交差点付近で歩行者が横断している。車は？","o":["歩行者の通行を妨げてはいけない","横断歩道がないので車が常に優先","歩行者にクラクションを鳴らして進む"],"a":0,"e":"横断歩道のない交差点やその近くでも、横断している歩行者の通行を妨げてはいけません。","sign":null},{"id":"CAR-036","mode":"car","q":"青信号でも先が渋滞し、交差点内で止まって他の交通を妨げそうな場合は？","o":["青なので進入する","交差点へ進入しない","対向車がいなければ進入する"],"a":1,"e":"青信号でも無条件に進めるわけではありません。交差点内で動けなくなり交差方向を妨げるおそれがある場合は進入禁止です。","sign":null},{"id":"CAR-037","mode":"car","q":"「止まれ」の標識で正しい停止方法は？","o":["十分低速なら完全停止不要","停止線直前などで一時停止する","タイヤが回っていても左右確認すればよい"],"a":1,"e":"一時停止は徐行とは異なります。停止線の直前、停止線がない場合は交差点の直前で一時停止する必要があります。","sign":null},{"id":"CAR-038","mode":"car","q":"無信号・優先道路指定なし・道路幅も同程度の交差点では、原則どちらが優先？","o":["左方から来る車","右方から来る車","車体の大きい車"],"a":0,"e":"交通整理がなく、優先道路や道路幅による優先関係もない同程度の道路では、左方から来る車が優先です。","sign":null},{"id":"CAR-039","mode":"car","q":"交差点付近で緊急自動車が接近した場合の基本は？","o":["青信号ならそのまま進む","交差点を避け、原則左側に寄って一時停止する","中央に寄って停止する"],"a":1,"e":"交差点またはその付近では交差点を避け、原則左側に寄って一時停止します。一方通行で左寄せが妨げになる場合は右側に寄れる例外があります。","sign":null},{"id":"CAR-040","mode":"car","q":"交差点付近以外で緊急自動車が接近した場合の基本は？","o":["必ずその場で完全停止","道路の左側に寄って進路を譲る","速度を上げて先に逃げる"],"a":1,"e":"交差点付近以外では、道路の左側に寄って進路を譲る必要がありますが、法令上『必ず完全停止』という同じ扱いではありません。","sign":null},{"id":"BIKE-021","mode":"bike","q":"自転車2台で横に並んで走ることについて正しいものは？","o":["後続車がいなければ自由","原則として禁止される","昼間だけ認められる"],"a":1,"e":"自転車の並進は原則禁止です。周囲に車がいるかどうかで自由になるルールではありません。『並進可』の標識がある場合などは別です。","sign":null},{"id":"BIKE-022","mode":"bike","q":"後輪ブレーキが壊れ、前輪ブレーキだけ効く自転車で公道を走ることは？","o":["前輪が効けば問題ない","必要な制動装置を備えないため問題がある","速度10km/h以下なら問題ない"],"a":1,"e":"必要な制動装置を備えない自転車を運転してはいけません。制動装置不良は悪質・危険な違反として青切符の対象になり得ます。","sign":null},{"id":"BIKE-023","mode":"bike","q":"自転車で踏切を通過するときの基本は？","o":["原則として直前で一時停止し安全確認","電車が見えなければ停止不要","歩行者がいなければ停止不要"],"a":0,"e":"自転車も車両です。原則として踏切直前で一時停止し、安全を確認して通過します。","sign":null},{"id":"BIKE-024","mode":"bike","q":"遮断機が下り始めた踏切に自転車で入ることは？","o":["閉じ切る前ならよい","進入してはいけない","ベルを鳴らせばよい"],"a":1,"e":"遮断機が閉じているときだけでなく、閉じようとしているときも踏切に入ってはいけません。","sign":null},{"id":"BIKE-025","mode":"bike","q":"自転車が交差点を右折するときの基本は？","o":["道路中央へ寄って小回り右折","二段階右折","右折は禁止"],"a":1,"e":"自転車は道路左側端に沿って交差点の向こう側まで進み、向きを変える二段階右折が原則です。","sign":null},{"id":"BIKE-026","mode":"bike","q":"対面信号が赤で青色の右向き矢印が出ているとき、自転車は？","o":["矢印に従ってそのまま右折できる","自転車は右向き矢印で右折できず、二段階右折の方法による","自転車だけ直進できる"],"a":1,"e":"右向きの青矢印でも、自転車など軽車両はその矢印で右折できません。自転車は二段階右折の方法によります。","sign":null},{"id":"BIKE-027","mode":"bike","q":"自転車で横断歩道を通行する場合について正しいものは？","o":["歩行者がいなくても必ず降りて押す義務がある","乗ったままの通行が一律禁止ではないが歩行者優先","横断歩道では自転車が常に優先"],"a":1,"e":"横断歩道を自転車で通行することが一律に禁止されているわけではありません。ただし横断歩道は歩行者優先で、歩行者の通行を妨げるおそれがある場合は乗ったまま通行すべきではありません。","sign":null},{"id":"BIKE-028","mode":"bike","q":"自転車で横断歩道に近づき、歩行者が渡ろうとしている場合は？","o":["自転車が先に通る","歩行者を優先する","ベルを鳴らせば通過できる"],"a":1,"e":"自転車も車両です。横断歩道では歩行者の優先ルールが適用され、横断中・横断しようとする歩行者がいれば一時停止して道を譲る必要があります。","sign":null},{"id":"BIKE-029","mode":"bike","q":"自転車横断帯が設けられている場所の付近を横断するときは？","o":["原則として自転車横断帯を利用する","好きな位置から横断する","歩道橋だけを使う"],"a":0,"e":"自転車横断帯がある場所の付近では、その自転車横断帯を進行して道路を横断します。","sign":null},{"id":"BIKE-030","mode":"bike","q":"2026年4月から、車が自転車の右側を十分な間隔を取れず通過する場合の自転車側の対応は？","o":["できる限り道路の左側に沿って進行する","道路中央へ寄る","必ず停止する"],"a":0,"e":"2026年4月1日施行の側方通過ルールです。十分な間隔がない場合、自転車側にもできる限り道路の左側に沿って進行する義務があります。","sign":null},{"id":"BIKE-031","mode":"bike","q":"2026年4月の側方通過ルールで「1m」について正しいものは？","o":["1m未満なら一律即違反となる固定距離","警察庁が安全の目安として示すが、一律の固定違反距離ではない","1m以上空けると違反になる"],"a":1,"e":"警察庁は安全の目安として1m程度を示していますが、1m未満を一律に違反とする固定距離規定ではありません。十分な間隔がない場合の自動車側の安全速度義務と、自転車側の左側寄り義務が定められています。","sign":null},{"id":"BIKE-032","mode":"bike","q":"黄色中央線などで後続車が自転車を追い越せない場合、自転車に一律に課される義務は？","o":["必ず停止して譲る義務","必ず歩道へ移る義務","『必ず停止して譲る』という一律の法的義務はない"],"a":2,"e":"『後続車を先に行かせるため必ず停止する』という一律の義務はありません。状況により安全な場所で任意に譲る配慮はできますが、法律上の義務とマナーは分けて考えます。なお2026年4月以降、十分な間隔がない状態で車が右側を通過する場合には、できる限り左側に沿う義務があります。","sign":null},{"id":"BIKE-033","mode":"bike","q":"片耳イヤホンを付けた自転車運転について正しいものは？","o":["装着しただけで必ず違反","安全運転に必要な音が十分聞こえるかが重要","片耳ならどんな音量でも問題ない"],"a":1,"e":"イヤホンの形や装着だけで直ちに違反と決まるものではありませんが、安全運転に必要な交通の音や声が聞こえない状態での運転は禁止されています。","sign":null},{"id":"BIKE-034","mode":"bike","q":"骨伝導イヤホンを使う自転車運転について正しいものは？","o":["骨伝導なら音量に関係なく合法","方式に関係なく安全に必要な音が聞こえることが重要","骨伝導は必ず違反"],"a":1,"e":"イヤホンの形や装着だけで直ちに違反と決まるものではありませんが、安全運転に必要な交通の音や声が聞こえない状態での運転は禁止されています。","sign":null},{"id":"BIKE-035","mode":"bike","q":"雨が弱い日に傘を手に持って自転車を運転することは？","o":["雨が弱ければよい","傘差し運転は問題となる","時速10km以下ならよい"],"a":1,"e":"傘を手に持つ運転は操作を妨げて危険で、各都道府県公安委員会の遵守事項にも従う必要があります。雨の強弱だけで許されるものではありません。","sign":null},{"id":"BIKE-036","mode":"bike","q":"傘固定器具を自転車に付けた場合について正しいものは？","o":["固定すれば条件を問わず必ず合法","視界・安定性・車体幅など他の条件も確認が必要","固定器具は全国で必ず違法"],"a":1,"e":"固定器具を使っていても、視界・安定性・車体や積載の制限など別のルールに抵触する可能性があります。『手で持っていない＝必ず合法』ではありません。","sign":null},{"id":"BIKE-037","mode":"bike","q":"歩道で歩行者に道を空けてもらうためベルを鳴らすことは？","o":["自由に鳴らしてよい","ベルはその目的で自由に使うものではない","3回までならよい"],"a":1,"e":"ベルは歩行者をどかすために自由に使うものではありません。指定場所や危険回避のためやむを得ない場合などを除き使用できません。","sign":null},{"id":"BIKE-038","mode":"bike","q":"「警笛鳴らせ」の標識がある場所で自転車は？","o":["自転車には関係ない","自転車も必要に応じベルを鳴らす義務がある","ベルを外していれば免除"],"a":1,"e":"自転車も車両であり、『警笛鳴らせ』の標識がある場所などでは警音器を鳴らす義務があります。","sign":null},{"id":"BIKE-039","mode":"bike","q":"自転車道が設けられている道路での普通自転車の通行は？","o":["原則として自転車道を通行する","歩道と車道から自由に選べる","必ず歩道を通行する"],"a":0,"e":"自転車道が設けられている道路では、原則として自転車道を通行する義務があります。","sign":null},{"id":"BIKE-040","mode":"bike","q":"自転車が路側帯を通行する場合の基本は？","o":["道路の右側の路側帯も自由に使える","道路の左側部分に設けられた路側帯を通行する","中央線に近い側を走る"],"a":1,"e":"自転車が路側帯を通行する場合は、道路の左側部分に設けられた路側帯を通行します。","sign":null},{"id":"CAR-041","mode":"car","q":"駐車場や車庫の自動車用出入口付近で、標識がない場合の駐車ルールは？","o":["標識がなければ自由に駐車できる","出入口から3m以内は駐車してはいけない","出入口の直前1mだけ駐車禁止"],"a":1,"e":"自動車用の出入口から3m以内は、標識がなくても駐車禁止です。","sign":null},{"id":"CAR-042","mode":"car","q":"交差点の側端から5m以内で、乗客を数秒で降ろす行為は？","o":["原則として停車できない","5分以内なら停車できる","ハザードを点ければ停車できる"],"a":0,"e":"交差点とその側端から5m以内は駐停車禁止場所です。","sign":null},{"id":"CAR-043","mode":"car","q":"横断歩道を通過して3m先で停車することは？","o":["歩行者がいなければできる","夜間だけできる","原則としてできない"],"a":2,"e":"横断歩道・自転車横断帯とその端から前後5m以内は駐停車禁止です。","sign":null},{"id":"CAR-044","mode":"car","q":"バス停の標示板から10m以内の駐停車禁止について正しいものは？","o":["バスが見えなければ運行時間中でも自由に停車できる","原則としてその路線の運行時間中に適用される","24時間必ず同じ規定で禁止される"],"a":1,"e":"バス停等から10m以内の駐停車禁止は、その停留所に係る運行時間中に適用されます。","sign":null},{"id":"CAR-045","mode":"car","q":"一般道路で後部座席に乗る人のシートベルトは？","o":["着用義務がある","高速道路だけ義務がある","運転者だけ着用すればよい"],"a":0,"e":"後部座席を含む全ての座席にシートベルト着用義務があります。","sign":null},{"id":"CAR-046","mode":"car","q":"6歳未満の幼児を自動車に乗せる場合の原則は？","o":["後部座席なら使用しなくてよい","大人が抱けば使用しなくてよい","チャイルドシートを使用させる"],"a":2,"e":"原則として6歳未満の幼児にはチャイルドシートを使用させる必要があります。","sign":null},{"id":"CAR-047","mode":"car","q":"運転中にスマートフォンを手に持って通話する行為は？","o":["片手運転できれば問題ない","画面を見ていなくても違反対象","通話だけなら問題ない"],"a":1,"e":"手に持って通話する行為も携帯電話使用等（保持）の対象です。","sign":null},{"id":"CAR-048","mode":"car","q":"ながらスマホで交通の危険を生じさせた場合の扱いは？","o":["通常の保持違反より重く、6点の対象となる","通常の保持違反と同じ3点","事故がなければ点数は付かない"],"a":0,"e":"交通の危険を生じさせた場合は6点で、通常の保持違反より重い扱いです。","sign":null},{"id":"CAR-049","mode":"car","q":"自転車との十分な側方間隔が取れない状態で右側を通過する自動車は？","o":["必ず1m以上空けられなければ停止する","制限速度内なら速度を変える必要はない","間隔に応じた安全な速度で進行する"],"a":2,"e":"2026年4月から、十分な間隔が取れない場合は間隔に応じた安全な速度で進行する義務があります。","sign":null},{"id":"CAR-050","mode":"car","q":"中央線等のない生活道路が法定30km/hでも「最高速度40」の標識がある場合は？","o":["最高速度20km/h","最高速度40km/h","最高速度30km/h"],"a":1,"e":"2026年9月1日以降も、標識・標示による指定速度がある場合は指定速度が優先されます。","sign":null},{"id":"BIKE-041","mode":"bike","q":"自転車が左側の路側帯を通行できる場合でも、歩行者を著しく妨げるときは？","o":["ベルを鳴らせば通行できる","その路側帯を通行してはいけない","自転車が優先なのでそのまま通行する"],"a":1,"e":"路側帯を通行できる場合でも、歩行者の通行を著しく妨げてはいけません。","sign":null},{"id":"BIKE-042","mode":"bike","q":"自転車から降りて押して歩く人は、原則としてどう扱われる？","o":["歩行者として扱われる","軽車両の運転者のまま","原動機付自転車と同じ扱い"],"a":0,"e":"自転車を押して歩く場合は、一定の例外を除き原則として歩行者とみなされます。","sign":null},{"id":"BIKE-043","mode":"bike","q":"普通自転車の大きさの基準として正しいものは？","o":["長さ250cm以内・幅100cm以内","長さ150cm以内・幅40cm以内","長さ190cm以内・幅60cm以内"],"a":2,"e":"普通自転車には長さ190cm以内、幅60cm以内などの構造基準があります。","sign":null},{"id":"BIKE-044","mode":"bike","q":"タンデム自転車と普通自転車の関係として正しいものは？","o":["歩道では歩行者として扱われる","タンデム自転車は普通自転車とは同じ扱いではない","必ず普通自転車として扱われる"],"a":1,"e":"タンデム自転車等は「普通自転車以外の自転車」の例で、普通自転車の歩道通行例外をそのまま使えません。","sign":null},{"id":"BIKE-045","mode":"bike","q":"自転車の二人乗りについて正しいものは？","o":["原則禁止だが、幼児同乗など地域ルールによる例外がある","全国で一切の例外なく禁止","後ろに荷台があれば成人同士でも自由に二人乗りできる"],"a":0,"e":"二人乗りは原則禁止ですが、幼児同乗など都道府県公安委員会規則による例外があります。","sign":null},{"id":"BIKE-046","mode":"bike","q":"自動車免許を持つ人が自転車で青切符を受けた場合、通常の免許点数は？","o":["必ず2点付く","違反内容に関係なく6点付く","自動車免許に通常の点数は付かない"],"a":2,"e":"自転車の交通違反で通常の自動車免許点数が付されることはありません。ただし重大な事故・違反では免許停止処分の可能性があります。","sign":null},{"id":"BIKE-047","mode":"bike","q":"自転車の危険行為を反復した場合は？","o":["何度繰り返しても講習制度はない","自転車運転者講習を命じられることがある","必ず自動車免許が取消しになる"],"a":1,"e":"一定の危険行為を反復した場合、公安委員会から自転車運転者講習を命じられることがあります。","sign":null},{"id":"BIKE-048","mode":"bike","q":"自転車運転者講習の受講命令に従わない場合は？","o":["5万円以下の罰金の対象","罰則はない","自転車を没収される"],"a":0,"e":"受講命令に従わなかった場合は5万円以下の罰金の対象です。","sign":null},{"id":"BIKE-049","mode":"bike","q":"自転車の青切符で反則金を納付しない場合は？","o":["必ず自動的に無効になる","何も起こらず終了する","刑事手続へ移行することがある"],"a":2,"e":"反則金を納付しない場合は、本来の刑事手続へ移行することがあります。","sign":null},{"id":"BIKE-050","mode":"bike","q":"自転車の青切符の反則金は取締り現場でどう支払う？","o":["警察官へ電子マネーで支払う","現場では警察官に現金で支払わない","警察官へ必ず現金払いする"],"a":1,"e":"警察官が取締り現場で反則金を徴収することはありません。納付書により金融機関等で納付します。","sign":null},{"id":"CAR-051","mode":"car","q":"画像の道路標識「通行止め」が示す意味として正しいものは？","o":["歩行者を含む全ての通行を禁止する","車両の種類ごとに通行する車線を指定する","前方にT字形の交差点があることを警告する"],"a":0,"e":"「通行止め」は、歩行者を含む全ての通行を禁止する標識です。","sign":"通行止め"},{"id":"CAR-052","mode":"car","q":"画像の道路標識「車両通行止め」が示す意味として正しいものは？","o":["特定の種類の車両が通行する区分を指定する","前方にY字形の交差点があることを警告する","車両の通行を禁止する"],"a":2,"e":"「車両通行止め」は、車両の通行を禁止する標識です。","sign":"車両通行止め"},{"id":"CAR-053","mode":"car","q":"画像の道路標識「二輪の自動車以外の自動車通行止め」が示す意味として正しいものは？","o":["前方にロータリーがあることを警告する","二輪車を除く自動車の通行を禁止する","特定の車両の専用通行帯を示す"],"a":1,"e":"「二